const today = new Date().toISOString().split('T')[0];

// 讀取表單回應
const formResponses = $('讀取今日表單數據').all()
  .map(i => i.json)
  .filter(r => r.提交時間 && r.提交時間.startsWith(today));

// 讀取知識日誌
const knowledgeItems = $('讀取今日知識日誌').all()
  .map(i => i.json)
  .filter(k => k.日期 && k.日期.startsWith(today));

// 計算KPI
const totalLeads = formResponses.length;
const hotLeads = formResponses.filter(r => parseInt(r.評分 || '0') >= 7).length;

const stats = {
  date: today,
  // 業務數據
  new_leads: totalLeads,
  hot_leads: hotLeads,
  conversion_rate: totalLeads > 0 ? ((hotLeads / totalLeads) * 100).toFixed(1) + '%' : '0%',
  // 知識學習
  knowledge_ingested: knowledgeItems.length,
  knowledge_categories: {},
  // 預算來源分布
  budget_distribution: {},
  // 購買意向分布
  timeline_distribution: {}
};

formResponses.forEach(r => {
  if (r.預算) {
    stats.budget_distribution[r.預算] = (stats.budget_distribution[r.預算] || 0) + 1;
  }
  if (r.購買時間) {
    stats.timeline_distribution[r.購買時間] = (stats.timeline_distribution[r.購買時間] || 0) + 1;
  }
});

knowledgeItems.forEach(k => {
  const cat = k.分類 || '未分類';
  stats.knowledge_categories[cat] = (stats.knowledge_categories[cat] || 0) + 1;
});

// 格式化簡報數據
const leadsText = formResponses.slice(0, 5).map(r =>
  `• ${r.姓名 || '匿名'} | ${r.預算 || '未填'} | ${r.購買時間 || '未填'}`
).join('\n') || '• 今日無新詢問';

const knowledgeText = knowledgeItems.slice(0, 5).map(k =>
  `• [${k.分類 || '未分類'}] ${k.標題 || ''}`.substring(0, 60)
).join('\n') || '• 今日無新知識攝取';

return [{
  json: {
    stats,
    leads_preview: leadsText,
    knowledge_preview: knowledgeText,
    raw_leads: formResponses,
    raw_knowledge: knowledgeItems
  }
}];

const report = $json.output || $json.text || '簡報生成失敗';
const stats = $('彙整每日數據').item.json.stats;

const telegramMessage = [
  `📊 *AI研發部門日報* ${stats.date}`,
  '',
  `📥 新詢問：${stats.new_leads} 人`,
  `🔥 高潛力：${stats.hot_leads} 人`,
  `📈 轉換率：${stats.conversion_rate}`,
  `📚 新知識：${stats.knowledge_ingested} 條`,
  '',
  '─────────────',
  report.substring(0, 2000),
  '─────────────',
  `⏰ 生成時間：${new Date().toLocaleTimeString('zh-TW')}`
].join('\n');

return [{
  json: {
    telegram_message: telegramMessage,
    full_report: report,
    stats
  }
}];
